const listInventoryStockLayersForUpdate = `-- name: ListInventoryStockLayersForUpdate :many
SELECT l.id,
       l.warehouse_id,
       l.sku_id,
       l.batch_id,
       l.received_at,
       l.on_hand_qty,
       l.reserved_qty
FROM inventory_stock_layers l
LEFT JOIN inventory_batches b
       ON b.id = l.batch_id
      AND b.deleted_at IS NULL
WHERE l.warehouse_id = $1::bigint
  AND l.sku_id = $2::bigint
  AND l.deleted_at IS NULL
  AND l.on_hand_qty - l.reserved_qty > 0
ORDER BY CASE
             WHEN $3::bigint IS NOT NULL
                  AND l.batch_id = $3::bigint THEN 0
             ELSE 1
         END,
         COALESCE(b.dispatch_priority, 10),
         l.received_at,
         l.id
FOR UPDATE OF l
`

type ListInventoryStockLayersForUpdateParams struct {
	WarehouseID int64  `db:"warehouse_id" json:"warehouse_id"`
	SkuID       int64  `db:"sku_id" json:"sku_id"`
	BatchID     *int64 `db:"batch_id" json:"batch_id"`
}

type ListInventoryStockLayersForUpdateRow struct {
	ID          int64              `db:"id" json:"id"`
	WarehouseID int64              `db:"warehouse_id" json:"warehouse_id"`
	SkuID       int64              `db:"sku_id" json:"sku_id"`
	BatchID     *int64             `db:"batch_id" json:"batch_id"`
	ReceivedAt  pgtype.Timestamptz `db:"received_at" json:"received_at"`
	OnHandQty   pgtype.Numeric     `db:"on_hand_qty" json:"on_hand_qty"`
	ReservedQty pgtype.Numeric     `db:"reserved_qty" json:"reserved_qty"`
}

// 分配顺序：指定 batch_id 时目标批次优先，随后按 dispatch_priority、received_at、id。
// 非批次层视为 dispatch_priority = 10。锁定库存层行，防止并发分配超扣。
func (q *Queries) ListInventoryStockLayersForUpdate(ctx context.Context, arg ListInventoryStockLayersForUpdateParams) ([]ListInventoryStockLayersForUpdateRow, error) {
	rows, err := q.db.Query(ctx, listInventoryStockLayersForUpdate, arg.WarehouseID, arg.SkuID, arg.BatchID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListInventoryStockLayersForUpdateRow
	for rows.Next() {
		var i ListInventoryStockLayersForUpdateRow
		if err := rows.Scan(
			&i.ID,
			&i.WarehouseID,
			&i.SkuID,
			&i.BatchID,
			&i.ReceivedAt,
			&i.OnHandQty,
			&i.ReservedQty,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

